import java.util.*;

class Solution {
    public long maximumScoreInBalancedString(String s) {
        List<Integer> opens = new ArrayList<>(), closes = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) if (s.charAt(i) == '(') opens.add(i);
        for (int i = s.length() - 1; i >= 0; i--) if (s.charAt(i) == ')') closes.add(i);
        long score = 0;
        for (int t = 0; t < Math.min(opens.size(), closes.size()); t++) {
            int o = opens.get(t), c = closes.get(t);
            if (c <= o) break;
            score += c - o;
        }
        return score;
    }
}

class Solution {
public:
    long long maximumScoreInBalancedString(string s) {
        vector<int> opens, closes;
        for (int i = 0; i < (int)s.size(); i++) if (s[i] == '(') opens.push_back(i);
        for (int i = (int)s.size() - 1; i >= 0; i--) if (s[i] == ')') closes.push_back(i);
        long long score = 0;
        for (size_t t = 0; t < min(opens.size(), closes.size()); t++) {
            if (closes[t] <= opens[t]) break;
            score += closes[t] - opens[t];
        }
        return score;
    }
};
